from pathlib import Path
import re

app=Path('dementor-lab/src/ui/app.mjs')
s=app.read_text()
s=s.replace("import { familyOf, canConnectNodes } from '../core/graph.mjs';","import { familyOf, canConnectNodes, outgoing } from '../core/graph.mjs';")
s=s.replace("let currentBrainGraph=structuredClone(actors.A.brainGraph),activeBrainNodeId=null,brainConnectFromId=null,activeBrainPresetId=null;","let currentBrainGraph=structuredClone(actors.A.brainGraph),activeBrainNodeId=null,brainConnectFromId=null,activeBrainPresetId=null,brainTriggerHubOpen=false,activeBrainTriggerId=null;")
s=s.replace("function applyBrainPreset(id){if(replayMode)return;const p=brainPreset(id);currentBrainGraph=cloneBrainGraph(p?.graph||BLANK_BRAIN);normalizeBrainStack();activeBrainPresetId=p?.id||'custom';activeBrainNodeId=null;brainConnectFromId=null;closeBrainControlSheet();renderBrain()}","function applyBrainPreset(id){if(replayMode)return;const p=brainPreset(id);currentBrainGraph=cloneBrainGraph(p?.graph||BLANK_BRAIN);normalizeBrainStack();activeBrainPresetId=p?.id||'custom';activeBrainNodeId=null;brainConnectFromId=null;activeBrainTriggerId=null;brainTriggerHubOpen=!p;closeBrainControlSheet();renderBrain()}")

old_rebuild=re.search(r"function rebuildBrainSequence\(\)\{.*?\}\nfunction normalizeBrainStack",s,re.S)
if not old_rebuild: raise SystemExit('rebuildBrainSequence not found')
new_rebuild=r'''function groupBrainNodes(){const triggers=currentBrainGraph.nodes.filter(n=>familyOf(n)==='TRIGGER'),body=currentBrainGraph.nodes.filter(n=>familyOf(n)!=='TRIGGER');currentBrainGraph.nodes=[...triggers,...body]}
function rebuildBrainSequence(){
  groupBrainNodes();markBrainEdgeKinds(currentBrainGraph);
  const triggers=currentBrainGraph.nodes.filter(n=>familyOf(n)==='TRIGGER'),body=currentBrainGraph.nodes.filter(n=>familyOf(n)!=='TRIGGER');
  const triggerIds=new Set(triggers.map(n=>n.id));
  const preserved=currentBrainGraph.edges.filter(e=>triggerIds.has(e.from)||e.uiManual||e.uiKind==='extra').map(e=>({...e,uiManual:e.uiManual||triggerIds.has(e.from)}));
  const byKey=new Map(preserved.map(e=>[`${e.from}->${e.to}`,e])),primary=[];
  for(let i=0;i<body.length-1;i++){const from=body[i],to=body[i+1],key=`${from.id}->${to.id}`;if(byKey.has(key))continue;const working={...currentBrainGraph,edges:[...preserved,...primary]};if(canConnectNodes(working,from,to))primary.push({id:primaryEdgeId(from.id,to.id),from:from.id,to:to.id,uiKind:'primary'})}
  if(triggers.length===1&&body.length&&!preserved.some(e=>e.from===triggers[0].id)){const from=triggers[0],to=body[0],working={...currentBrainGraph,edges:[...preserved,...primary]};if(canConnectNodes(working,from,to))preserved.push({id:primaryEdgeId(from.id,to.id),from:from.id,to:to.id,uiKind:'extra',uiManual:true})}
  currentBrainGraph.edges=[...preserved,...primary];currentBrainGraph.nodes.forEach((node,i)=>{node.ui={...(node.ui||{}),x:0,y:i*82}})
}
function normalizeBrainStack'''
s=s[:old_rebuild.start()]+new_rebuild+s[old_rebuild.end():]

old_reorder=re.search(r"function reorderBrainNode\(id,targetIndex\)\{.*?\}\nfunction bindBrainStackDrag",s,re.S)
if not old_reorder: raise SystemExit('reorderBrainNode not found')
new_reorder=r'''function reorderBrainNode(id,targetIndex){const node=currentBrainGraph.nodes.find(n=>n.id===id);if(!node||familyOf(node)==='TRIGGER')return;const triggers=currentBrainGraph.nodes.filter(n=>familyOf(n)==='TRIGGER'),body=currentBrainGraph.nodes.filter(n=>familyOf(n)!=='TRIGGER'),from=body.findIndex(n=>n.id===id);if(from<0||targetIndex===from)return;const [moved]=body.splice(from,1),bounded=Math.max(0,Math.min(body.length,targetIndex));body.splice(bounded,0,moved);currentBrainGraph.nodes=[...triggers,...body];rebuildBrainSequence();activeBrainPresetId='custom'}
function bindBrainStackDrag'''
s=s[:old_reorder.start()]+new_reorder+s[old_reorder.end():]

marker='function renderBrainCanvas()'
pos=s.find(marker)
if pos<0: raise SystemExit('renderBrainCanvas marker not found')
helpers=r'''function brainTriggerNodes(){return currentBrainGraph.nodes.filter(n=>familyOf(n)==='TRIGGER')}
function triggerRoute(triggerId){const seen=new Set(),stack=[triggerId];while(stack.length){const id=stack.pop();if(seen.has(id))continue;seen.add(id);for(const edge of outgoing(currentBrainGraph,id))stack.push(edge.to)}return seen}
function triggerDestination(node){const first=outgoing(currentBrainGraph,node.id)[0],target=first&&currentBrainGraph.nodes.find(n=>n.id===first.to);return target?title(target.type):'НЕ ПОДКЛЮЧЕНО'}
function triggerHubHtml(){const triggers=brainTriggerNodes(),active=activeBrainTriggerId&&triggers.some(n=>n.id===activeBrainTriggerId)?activeBrainTriggerId:null;const chips=triggers.map(n=>`<button type="button" class="brain-trigger-chip ${n.id===active?'active':''}" data-trigger-select="${n.id}">${title(n.type)}</button>`).join('');const rows=triggers.map(n=>`<div class="brain-trigger-row ${n.id===active?'active':''}" data-trigger-row="${n.id}"><button type="button" class="brain-trigger-row__main" data-trigger-select="${n.id}"><strong>${title(n.type)}</strong><span>${nodeSubtitle(n)}</span><em>→ ${triggerDestination(n)}</em></button>${replayMode?'':`<div class="brain-trigger-row__actions"><button type="button" data-trigger-connect="${n.id}">СВЯЗАТЬ</button><button type="button" data-trigger-delete="${n.id}" aria-label="Удалить ${title(n.type)}">×</button></div>`}</div>`).join('');return `<section class="brain-trigger-hub ${brainTriggerHubOpen?'open':''}" data-trigger-hub><button type="button" class="brain-trigger-hub__head" data-trigger-hub-toggle aria-expanded="${brainTriggerHubOpen}"><span><small>ВХОДЫ</small><strong>${triggers.length?'НА ЧТО Я РЕАГИРУЮ':'НА ЧТО ТЫ РЕАГИРУЕШЬ?'}</strong></span><b>${triggers.length}</b><i>${brainTriggerHubOpen?'−':'+'}</i></button>${triggers.length?`<div class="brain-trigger-chips">${chips}</div>`:'<p class="brain-trigger-empty">ДОБАВЬ ПЕРВЫЙ TRIGGER ЧЕРЕЗ «+ УЗЕЛ».</p>'}<div class="brain-trigger-hub__body">${rows}</div></section>`}
function bindTriggerHub(){const host=$('#brain-graph');host?.querySelector('[data-trigger-hub-toggle]')?.addEventListener('click',()=>{brainTriggerHubOpen=!brainTriggerHubOpen;renderBrainCanvas()});host?.querySelectorAll('[data-trigger-select]').forEach(button=>button.addEventListener('click',()=>{activeBrainTriggerId=activeBrainTriggerId===button.dataset.triggerSelect?null:button.dataset.triggerSelect;brainTriggerHubOpen=true;brainConnectFromId=null;activeBrainNodeId=null;renderBrainCanvas();renderBrainStatus()}));host?.querySelectorAll('[data-trigger-connect]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.triggerConnect;activeBrainTriggerId=id;brainConnectFromId=brainConnectFromId===id?null:id;activeBrainNodeId=null;renderBrainCanvas();renderBrainStatus()}));host?.querySelectorAll('[data-trigger-delete]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.triggerDelete;if(activeBrainTriggerId===id)activeBrainTriggerId=null;deleteBrainNode(id)}))}
function projectedBrainNodeHtml(n,route){const html=brainNodeHtml(n);if(!activeBrainTriggerId)return html;return html.replace('brain-stack-node ',`brain-stack-node ${route.has(n.id)?'route-active':'route-muted'} `)}
'''
s=s[:pos]+helpers+s[pos:]

canvas=re.search(r"function renderBrainCanvas\(\)\{.*?\}\nfunction showNodeLibrary",s,re.S)
if not canvas: raise SystemExit('renderBrainCanvas block not found')
new_canvas=r'''function renderBrainCanvas(){const host=$('#brain-graph');if(!host)return;groupBrainNodes();normalizeBrainStack();const route=activeBrainTriggerId?triggerRoute(activeBrainTriggerId):new Set(),body=currentBrainGraph.nodes.filter(n=>familyOf(n)!=='TRIGGER');host.dataset.edgeCount=String(currentBrainGraph.edges.length);host.dataset.connectFrom=brainConnectFromId||'';host.dataset.activeTrigger=activeBrainTriggerId||'';host.innerHTML=`${triggerHubHtml()}<svg class="brain-stack-links" aria-hidden="true"></svg><div class="brain-stack-list">${body.map(n=>projectedBrainNodeHtml(n,route)).join('')}</div>`;bindTriggerHub();host.querySelectorAll('[data-brain-node]').forEach(button=>button.addEventListener('click',()=>selectBrainNode(button.dataset.brainNode)));host.querySelectorAll('[data-brain-connect]').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();beginBrainConnection(button.dataset.brainConnect)}));host.querySelectorAll('[data-brain-param]').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();showBrainControlSheet(button.dataset.brainParam)}));host.querySelectorAll('[data-brain-delete]').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();deleteBrainNode(button.dataset.brainDelete)}));host.querySelectorAll('[data-brain-target]').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();finishBrainConnection(button.dataset.brainTarget)}));bindBrainStackDrag();requestAnimationFrame(drawBrainEdges)}
function showNodeLibrary'''
s=s[:canvas.start()]+new_canvas+s[canvas.end():]

# Keep selected trigger route after explicit connection, and do not pretend trigger is a stack card.
s=s.replace("if(made){made.uiKind='extra';made.uiManual=true;brainConnectFromId=null;activeBrainNodeId=null;activeBrainPresetId='custom'}","if(made){made.uiKind='extra';made.uiManual=true;if(familyOf(fromBrainNode(brainConnectFromId))==='TRIGGER')activeBrainTriggerId=brainConnectFromId;brainConnectFromId=null;activeBrainNodeId=null;activeBrainPresetId='custom'}")
# helper for the line above
s=s.replace("function finishBrainConnection(id)","function fromBrainNode(id){return currentBrainGraph.nodes.find(n=>n.id===id)||null}\nfunction finishBrainConnection(id)")
app.write_text(s)

css=Path('dementor-lab/brain-stack.css')
cs=css.read_text()
cs += r'''
/* Trigger Hub: runtime nodes remain real; mobile projection groups entry infrastructure. */
.brain-trigger-hub{position:relative;z-index:5;margin:0 0 14px;border:2px solid var(--ink);background:var(--paper)}
.brain-trigger-hub__head{width:100%;min-height:66px;border:0;background:var(--ink);color:var(--paper);display:grid;grid-template-columns:1fr 34px 26px;align-items:center;gap:8px;padding:9px 12px;text-align:left}
.brain-trigger-hub__head:active{transform:none}.brain-trigger-hub__head span{min-width:0}.brain-trigger-hub__head small{display:block;font-size:10px;letter-spacing:.08em;opacity:.62}.brain-trigger-hub__head strong{display:block;font-size:16px;line-height:1.05}.brain-trigger-hub__head b{display:grid;place-items:center;width:30px;height:30px;background:var(--acid);color:var(--ink);font:900 15px/1 monospace}.brain-trigger-hub__head i{font:900 25px/1 monospace;font-style:normal;text-align:center}.brain-trigger-chips{display:flex;gap:6px;padding:8px;overflow-x:auto;scrollbar-width:none;border-top:1px solid var(--ink)}.brain-trigger-chips::-webkit-scrollbar{display:none}.brain-trigger-chip{flex:0 0 auto;min-height:34px;margin:0;border:1px solid var(--ink);background:var(--paper);color:var(--ink);padding:6px 9px;font-size:10px;font-weight:900;white-space:nowrap}.brain-trigger-chip.active{background:var(--acid)}.brain-trigger-chip:active{transform:none}.brain-trigger-hub__body{display:none;border-top:2px solid var(--ink)}.brain-trigger-hub.open .brain-trigger-hub__body{display:block}.brain-trigger-row{display:grid;grid-template-columns:minmax(0,1fr) auto;border-bottom:1px solid var(--ink)}.brain-trigger-row:last-child{border-bottom:0}.brain-trigger-row.active{background:var(--acid)}.brain-trigger-row__main{min-width:0;border:0;background:transparent;color:inherit;text-align:left;padding:10px 9px}.brain-trigger-row__main:active{transform:none}.brain-trigger-row__main strong,.brain-trigger-row__main span,.brain-trigger-row__main em{display:block}.brain-trigger-row__main strong{font-size:13px}.brain-trigger-row__main span{font-size:10px;line-height:1.15;margin-top:2px;opacity:.72}.brain-trigger-row__main em{font:900 10px/1.15 monospace;margin-top:5px;font-style:normal}.brain-trigger-row__actions{display:flex;align-items:stretch}.brain-trigger-row__actions button{min-width:54px;margin:0;border:0;border-left:1px solid var(--ink);background:transparent;color:inherit;padding:0 8px;font-size:9px;font-weight:900}.brain-trigger-row__actions button:last-child{min-width:38px;font-size:20px}.brain-trigger-row__actions button:active{transform:none}.brain-trigger-empty{margin:0;padding:11px;font:900 11px/1.2 monospace;border-top:1px solid var(--ink)}.brain-stack-node.route-muted{opacity:.22}.brain-stack-node.route-active .brain-stack-card{outline:3px solid var(--acid);outline-offset:-3px}.brain-trigger-hub + .brain-stack-links{top:auto}
@media(max-width:430px){.brain-trigger-hub__head strong{font-size:15px}.brain-trigger-row__actions button{min-width:50px;padding:0 6px}}
'''
css.write_text(cs)

browser=Path('dementor-lab/tests/browser-smoke.mjs')
b=browser.read_text()
b=b.replace("assert.equal(await page.locator('#brain-graph .brain-stack-node').count(),3,'stack editor renders the three real graph nodes');","assert.equal(await page.locator('#brain-graph [data-trigger-hub]').count(),1,'BRAIN projects trigger infrastructure into one hub');assert.equal(await page.locator('#brain-graph .brain-trigger-chip').count(),1,'custom graph exposes one real trigger as a chip');assert.equal(await page.locator('#brain-graph .brain-stack-node').count(),2,'main stack shows behavioral body without duplicating trigger infrastructure');")
b=b.replace("const triggerWrap=page.locator('#brain-graph .brain-stack-node').filter({hasText:'КРИТИКА'}).first();const impulseWrap=page.locator('#brain-graph .brain-stack-node').filter({hasText:'БЫТЬ ПРАВЫМ'}).first();const reactionWrap=page.locator('#brain-graph .brain-stack-node').filter({hasText:'ОБЪЯСНИТЬ'}).first();\nconst triggerId=await triggerWrap.getAttribute('data-brain-node-wrap'),impulseId=await impulseWrap.getAttribute('data-brain-node-wrap'),reactionId=await reactionWrap.getAttribute('data-brain-node-wrap');","const impulseWrap=page.locator('#brain-graph .brain-stack-node').filter({hasText:'БЫТЬ ПРАВЫМ'}).first();const reactionWrap=page.locator('#brain-graph .brain-stack-node').filter({hasText:'ОБЪЯСНИТЬ'}).first();\nconst triggerId=await page.locator('#brain-graph .brain-trigger-chip').first().getAttribute('data-trigger-select'),impulseId=await impulseWrap.getAttribute('data-brain-node-wrap'),reactionId=await reactionWrap.getAttribute('data-brain-node-wrap');")
b=b.replace("await page.locator(`[data-brain-node=\"${triggerId}\"]`).click();await page.locator(`[data-brain-connect=\"${triggerId}\"]`).click();assert.equal(await page.locator('#brain-graph').getAttribute('data-connect-from'),triggerId,'connect action activates a real graph source');assert.ok(await page.locator('#brain-graph .connection-target').count()>=1,'only compatible target cards highlight');await page.locator(`[data-brain-target=\"${reactionId}\"]`).click();await page.waitForTimeout(34);assert.equal(await page.locator('#brain-graph .brain-stack-edge.extra').count(),1,'manual connection renders as one extra bracket over the primary sequence');\nconst manualEdgeId=await page.locator('#brain-graph .brain-stack-edge.extra').first().getAttribute('data-edge');const reactionHandle=page.locator(`[data-brain-drag=\"${reactionId}\"]`),reactionHandleBox=await reactionHandle.boundingBox(),impulseBox=await impulseWrap.boundingBox();assert.ok(reactionHandleBox&&impulseBox,'drag geometry exists');await page.mouse.move(reactionHandleBox.x+reactionHandleBox.width/2,reactionHandleBox.y+reactionHandleBox.height/2);await page.mouse.down();await page.mouse.move(reactionHandleBox.x+reactionHandleBox.width/2,impulseBox.y+impulseBox.height/2,{steps:4});await page.mouse.up();await page.waitForTimeout(40);assert.equal(await page.locator(`[data-edge=\"${manualEdgeId}\"]`).count(),1,'manual branch survives reorder even when it becomes adjacent');","await page.locator('[data-trigger-hub-toggle]').click();assert.equal(await page.locator('[data-trigger-row]').count(),1,'hub expands to the real entry node');await page.locator(`[data-trigger-connect=\"${triggerId}\"]`).click();assert.equal(await page.locator('#brain-graph').getAttribute('data-connect-from'),triggerId,'hub connect action activates the real trigger node');assert.ok(await page.locator('#brain-graph .connection-target').count()>=1,'compatible behavioral cards highlight from a hidden trigger source');await page.locator(`[data-brain-target=\"${reactionId}\"]`).click();await page.waitForTimeout(34);assert.match(await page.locator(`[data-trigger-row=\"${triggerId}\"]`).textContent(),/ОБЪЯСНИТЬ/,'hub exposes the trigger destination instead of hiding causality');assert.ok(await page.locator('#brain-graph .route-active').count()>=1,'selecting/connecting a trigger highlights its downstream route');const reactionHandle=page.locator(`[data-brain-drag=\"${reactionId}\"]`),reactionHandleBox=await reactionHandle.boundingBox(),impulseBox=await impulseWrap.boundingBox();assert.ok(reactionHandleBox&&impulseBox,'drag geometry exists');await page.mouse.move(reactionHandleBox.x+reactionHandleBox.width/2,reactionHandleBox.y+reactionHandleBox.height/2);await page.mouse.down();await page.mouse.move(reactionHandleBox.x+reactionHandleBox.width/2,impulseBox.y+impulseBox.height/2,{steps:4});await page.mouse.up();await page.waitForTimeout(40);assert.equal(await page.locator(`[data-trigger-row=\"${triggerId}\"]`).count(),1,'trigger hub survives body reorder');")
b=b.replace("assert.equal(await page.locator('#brain-graph .brain-stack-node').count(),11,'collision-ready preset plus extra repeat renders all real graph nodes');","assert.equal(await page.locator('#brain-graph .brain-trigger-chip').count(),6,'collision-ready preset keeps six real entry triggers in the hub');assert.equal(await page.locator('#brain-graph .brain-stack-node').count(),5,'preset body stays compact after trigger infrastructure is projected into the hub');")
b=b.replace("console.log('DEMENTOR LAB browser smoke: PASS — exact characters and stacked BRAIN editor work in phone-sized flow');","console.log('DEMENTOR LAB browser smoke: PASS — exact characters, Trigger Hub and stacked BRAIN body work in phone-sized flow');")
browser.write_text(b)

# Self-cleaning workflow. Restore standard QA and remove this script after patch commit.
workflow=Path('.github/workflows/dementor-lab-vertical-slice-qa.yml')
workflow.write_text('''name: Apply Dementor Trigger Hub\n\non:\n  push:\n    branches:\n      - agent/dementor-lab-vertical-slice-v0.3\n    paths:\n      - 'dementor-lab/scripts/trigger-hub-patch.py'\n      - '.github/workflows/dementor-lab-vertical-slice-qa.yml'\n\npermissions:\n  contents: write\n\njobs:\n  trigger-hub:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - run: python3 dementor-lab/scripts/trigger-hub-patch.py\n      - run: rm dementor-lab/scripts/trigger-hub-patch.py\n      - run: |\n          cat > .github/workflows/dementor-lab-vertical-slice-qa.yml <<'YAML'\n          name: Dementor Lab Vertical Slice QA\n\n          on:\n            push:\n              branches:\n                - agent/dementor-lab-vertical-slice-v0.3\n              paths:\n                - 'dementor-lab/**'\n                - '.github/workflows/dementor-lab-vertical-slice-qa.yml'\n            workflow_dispatch:\n\n          permissions:\n            contents: read\n\n          jobs:\n            deterministic-qa:\n              runs-on: ubuntu-latest\n              defaults:\n                run:\n                  working-directory: dementor-lab\n              steps:\n                - name: Checkout\n                  uses: actions/checkout@v4\n                - name: Setup Node\n                  uses: actions/setup-node@v4\n                  with:\n                    node-version: '22'\n                - name: Run zero-dependency QA suite\n                  run: npm test\n\n            browser-smoke:\n              runs-on: ubuntu-latest\n              needs: deterministic-qa\n              defaults:\n                run:\n                  working-directory: dementor-lab\n              steps:\n                - name: Checkout\n                  uses: actions/checkout@v4\n                - name: Setup Node\n                  uses: actions/setup-node@v4\n                  with:\n                    node-version: '22'\n                - name: Install Playwright for QA only\n                  run: npm install --no-save playwright@1.55.0\n                - name: Install Chromium\n                  run: npx playwright install --with-deps chromium\n                - name: Start static server\n                  run: python3 -m http.server 4173 --bind 127.0.0.1 > /tmp/dementor-lab-http.log 2>&1 &\n                - name: Wait for static server\n                  run: |\n                    for i in {1..20}; do\n                      curl -fsS http://127.0.0.1:4173/ >/dev/null && exit 0\n                      sleep 1\n                    done\n                    cat /tmp/dementor-lab-http.log\n                    exit 1\n                - name: Run iPhone-sized browser smoke\n                  run: DEMENTOR_LAB_URL=http://127.0.0.1:4173 node tests/browser-smoke.mjs\n          YAML\n      - run: |\n          git config user.name SLEDZARI\n          git config user.email sharecraftwideo@gmail.com\n          git add dementor-lab/src/ui/app.mjs dementor-lab/brain-stack.css dementor-lab/tests/browser-smoke.mjs dementor-lab/scripts/trigger-hub-patch.py .github/workflows/dementor-lab-vertical-slice-qa.yml\n          git commit -m "feat(lab): add mobile trigger hub projection"\n          git push\n''')
